questionvariables.text:
/* Random edge length of the regular tetrahedron */
a: 2+rand(9);

/* Distance from the centre O to each vertex */
OA: a*sqrt(6)/4;

/* Length of edge AB */
AB: a;

/* Cosine rule applied to triangle AOB */
ta_cos: (OA^2+OA^2-AB^2)/(2*OA^2);

/* Exact trigonometric ratios */
ta_sin: 2*sqrt(2)/3;
ta_tan: -2*sqrt(2);

/* Quadrant containing the angle */
ta_quad: 2;
